<template>
  <div class="page-webhooks">
    <div class="page-header">
      <h2>{{ t('settings.webhooks.title') }}</h2>
      <div v-if="hasKey">
        <el-button @click="onChangeKey">{{ t('settings.webhooks.changeKey') }}</el-button>
        <el-button type="primary" @click="onCreate">{{ t('settings.webhooks.createSubscription') }}</el-button>
      </div>
    </div>

    <!-- API Key 输入态：开放 API 走 Bearer 认证，控制台 cookie 会话不可用 -->
    <el-card v-if="!hasKey">
      <el-alert
        type="info"
        :closable="false"
        :title="t('settings.webhooks.keyAlert')"
        style="margin-bottom: 16px"
      />
      <el-form inline @submit.prevent>
        <el-form-item label="API Key">
          <el-input
            v-model="keyInput"
            type="password"
            show-password
            :placeholder="t('settings.webhooks.keyPlaceholder')"
            style="width: 360px"
          />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" :disabled="!keyInput.trim()" @click="onSaveKey">
            {{ t('settings.webhooks.saveAndLoad') }}
          </el-button>
          <router-link to="/settings/api-keys">
            <el-button link type="primary">{{ t('settings.webhooks.gotoApiKeys') }}</el-button>
          </router-link>
        </el-form-item>
      </el-form>
    </el-card>

    <template v-else>
      <el-card>
        <DataTable
          :data="webhooks"
          :loading="loading"
          v-model:current-page="page"
          v-model:page-size="pageSize"
          :total="total"
          server-side
          @page-change="loadWebhooks"
          @size-change="loadWebhooks"
        >
          <el-table-column prop="id" label="ID" width="80" />
          <el-table-column prop="url" :label="t('settings.webhooks.callbackUrl')" min-width="260" show-overflow-tooltip />
          <el-table-column :label="t('settings.webhooks.events')" min-width="240">
            <template #default="{ row }">
              <el-tag v-for="e in row.events" :key="e" size="small" style="margin-right: 4px">
                {{ e }}
              </el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="enabled" :label="t('common.status')" width="90">
            <template #default="{ row }">
              <el-tag :type="row.enabled ? 'success' : 'info'" size="small">
                {{ row.enabled ? t('common.enabled') : t('settings.webhooks.stopped') }}
              </el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="last_triggered_at" :label="t('settings.webhooks.lastDelivery')" width="180">
            <template #default="{ row }">
              {{ row.last_triggered_at || t('common.never') }}
            </template>
          </el-table-column>
          <el-table-column :label="t('common.actions')" width="140" fixed="right">
            <template #default="{ row }">
              <el-button link type="primary" size="small" @click="onDetail(row)">{{ t('common.detail') }}</el-button>
              <el-button link type="danger" size="small" @click="onDelete(row)">{{ t('common.delete') }}</el-button>
            </template>
          </el-table-column>
        </DataTable>
      </el-card>

      <!-- 创建对话框 -->
      <el-dialog
        v-model="dialogVisible"
        :title="t('settings.webhooks.createDialogTitle')"
        width="560px"
        :close-on-click-modal="false"
        @closed="resetForm"
      >
        <el-form ref="formRef" :model="form" :rules="rules" label-width="100px">
          <el-form-item :label="t('settings.webhooks.callbackUrl')" prop="url">
            <el-input v-model="form.url" placeholder="https://example.com/webhook" />
          </el-form-item>
          <el-form-item :label="t('settings.webhooks.eventType')" prop="events">
            <el-checkbox-group v-model="form.events">
              <el-checkbox v-for="e in WEBHOOK_EVENTS" :key="e" :label="e" :value="e" />
            </el-checkbox-group>
          </el-form-item>
          <el-form-item :label="t('common.enable')">
            <el-switch v-model="form.enabled" />
          </el-form-item>
        </el-form>
        <template #footer>
          <el-button @click="dialogVisible = false">{{ t('common.cancel') }}</el-button>
          <el-button type="primary" :loading="submitting" @click="onSubmit">{{ t('common.create') }}</el-button>
        </template>
      </el-dialog>

      <!-- 一次性 secret 展示对话框 -->
      <el-dialog
        v-model="secretDialogVisible"
        :title="t('settings.webhooks.secretDialogTitle')"
        width="560px"
        :close-on-click-modal="false"
      >
        <el-alert
          type="error"
          :closable="false"
          :title="t('settings.webhooks.secretAlert')"
          style="margin-bottom: 12px"
        />
        <el-input v-model="lastSecret" readonly>
          <template #append>
            <el-button @click="copySecret">{{ t('common.copy') }}</el-button>
          </template>
        </el-input>
        <template #footer>
          <el-button type="primary" @click="secretDialogVisible = false">{{ t('common.saved') }}</el-button>
        </template>
      </el-dialog>

      <!-- 详情对话框 -->
      <el-dialog v-model="detailVisible" :title="t('settings.webhooks.detailDialogTitle')" width="560px">
        <el-descriptions v-if="detail" :column="1" border>
          <el-descriptions-item label="ID">{{ detail.id }}</el-descriptions-item>
          <el-descriptions-item :label="t('settings.webhooks.callbackUrl')">{{ detail.url }}</el-descriptions-item>
          <el-descriptions-item :label="t('settings.webhooks.eventType')">
            <el-tag v-for="e in detail.events" :key="e" size="small" style="margin-right: 4px">
              {{ e }}
            </el-tag>
          </el-descriptions-item>
          <el-descriptions-item :label="t('common.status')">
            {{ detail.enabled ? t('common.enabled') : t('settings.webhooks.stopped') }}
          </el-descriptions-item>
          <el-descriptions-item :label="t('common.createdAt')">{{ detail.created_at }}</el-descriptions-item>
          <el-descriptions-item :label="t('common.updatedAt')">{{ detail.updated_at }}</el-descriptions-item>
          <el-descriptions-item :label="t('settings.webhooks.lastDelivery')">
            {{ detail.last_triggered_at || t('common.never') }}
          </el-descriptions-item>
        </el-descriptions>
      </el-dialog>
    </template>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import {
  WEBHOOK_EVENTS,
  clearStoredWebhookApiKey,
  createWebhook,
  deleteWebhook,
  getStoredWebhookApiKey,
  getWebhooks,
  isWebhookAuthError,
  setStoredWebhookApiKey,
  type WebhookRead,
} from '@/api/webhooks'
import DataTable from '@/components/common/DataTable.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const keyInput = ref('')
// sessionStorage 非响应式，用显式 ref 跟踪 Key 输入态
const hasKey = ref(!!getStoredWebhookApiKey())

const webhooks = ref<WebhookRead[]>([])
const loading = ref(false)
const page = ref(1)
const pageSize = ref(20)
const total = ref(0)

const dialogVisible = ref(false)
const secretDialogVisible = ref(false)
const detailVisible = ref(false)
const lastSecret = ref('')
const submitting = ref(false)
const formRef = ref<FormInstance>()
const detail = ref<WebhookRead | null>(null)

const form = ref<{ url: string; events: string[]; enabled: boolean }>({
  url: '',
  events: ['alert.firing', 'alert.resolved'],
  enabled: true,
})

const rules: FormRules = {
  url: [{ required: true, message: () => t('settings.webhooks.urlRequired'), trigger: 'blur' }],
  events: [
    {
      validator: (_r, v: string[], cb) =>
        v && v.length > 0 ? cb() : cb(new Error(t('settings.webhooks.eventsRequired'))),
      trigger: 'change',
    },
  ],
}

/** 认证失效时清除已存 Key，退回输入态（computed hasKey 自动翻转）。 */
function handleAuthFailure(error: unknown) {
  clearStoredWebhookApiKey()
  hasKey.value = false
  showError(error, t('settings.webhooks.authInvalid'))
}

function onSaveKey() {
  setStoredWebhookApiKey(keyInput.value)
  keyInput.value = ''
  hasKey.value = true
  loadWebhooks()
}

function onChangeKey() {
  clearStoredWebhookApiKey()
  hasKey.value = false
}

async function loadWebhooks() {
  if (!hasKey.value) return
  loading.value = true
  try {
    const result = await getWebhooks({ page: page.value, page_size: pageSize.value })
    webhooks.value = result.items
    total.value = result.total
  } catch (error) {
    if (isWebhookAuthError(error)) {
      handleAuthFailure(error)
    } else {
      showError(error, t('settings.webhooks.loadFailed'))
    }
  } finally {
    loading.value = false
  }
}

function resetForm() {
  form.value = { url: '', events: ['alert.firing', 'alert.resolved'], enabled: true }
  formRef.value?.resetFields()
}

function onCreate() {
  resetForm()
  dialogVisible.value = true
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const created = await createWebhook({
      url: form.value.url,
      events: form.value.events,
      enabled: form.value.enabled,
    })
    dialogVisible.value = false
    lastSecret.value = created.secret
    secretDialogVisible.value = true
    loadWebhooks()
  } catch (error) {
    if (isWebhookAuthError(error)) {
      handleAuthFailure(error)
    } else {
      showError(error, t('settings.webhooks.createFailed'))
    }
  } finally {
    submitting.value = false
  }
}

function onDetail(row: WebhookRead) {
  detail.value = row
  detailVisible.value = true
}

async function onDelete(row: WebhookRead) {
  try {
    await ElMessageBox.confirm(
      t('settings.webhooks.confirmDelete', { id: row.id, url: row.url }),
      t('settings.webhooks.confirmDeleteTitle'),
      {
        type: 'warning',
      }
    )
  } catch {
    return // 用户取消
  }
  try {
    await deleteWebhook(row.id)
    ElMessage.success(t('settings.webhooks.deleted'))
    loadWebhooks()
  } catch (error) {
    if (isWebhookAuthError(error)) {
      handleAuthFailure(error)
    } else {
      showError(error, t('settings.webhooks.deleteFailed'))
    }
  }
}

async function copySecret() {
  try {
    await navigator.clipboard.writeText(lastSecret.value)
    ElMessage.success(t('settings.webhooks.copied'))
  } catch {
    ElMessage.warning(t('settings.webhooks.copyFailedManual'))
  }
}

onMounted(loadWebhooks)
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}
</style>
