/** Webhook 订阅管理（开放 API `/api/open/v1/webhooks` 的 Web 代管封装）。
 *
 * 注意：开放 API 走 API Key（Bearer）认证，不使用控制台 cookie 会话。
 * 本模块使用独立的 axios 实例，明文 Key 由用户在页面输入后存于 sessionStorage
 * （仅当前标签页会话有效），请求拦截器统一注入 Authorization 头。
 * Key 需具备 `read:webhooks` scope；创建/删除还要求 Key 绑定用户为 admin。
 */
import axios, { AxiosError } from 'axios'
import type { Page, PageParams } from './page'

/** 支持的订阅事件类型，与后端 VALID_WEBHOOK_EVENTS 保持一致。 */
export const WEBHOOK_EVENTS = [
  'alert.firing',
  'alert.resolved',
  'incident.created',
  'incident.resolved',
  'node.online',
  'node.offline',
] as const

export interface WebhookRead {
  id: number
  user_id: number
  url: string
  events: string[]
  enabled: boolean
  created_at: string
  updated_at: string
  last_triggered_at: string | null
}

export interface WebhookCreate {
  url: string
  events: string[]
  enabled?: boolean
}

/** 创建响应：额外包含仅此一次回显的 secret（验签用）。 */
export interface WebhookCreateResponse extends WebhookRead {
  secret: string
}

const STORAGE_KEY = 'chaosops_webhook_api_key'

export function getStoredWebhookApiKey(): string {
  return sessionStorage.getItem(STORAGE_KEY) || ''
}

export function setStoredWebhookApiKey(key: string): void {
  sessionStorage.setItem(STORAGE_KEY, key.trim())
}

export function clearStoredWebhookApiKey(): void {
  sessionStorage.removeItem(STORAGE_KEY)
}

/** 是否为认证错误（Key 失效/缺失），页面据此退回 Key 输入态。 */
export function isWebhookAuthError(err: unknown): boolean {
  const status = (err as AxiosError)?.response?.status
  return status === 401 || status === 403
}

const webhookClient = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || '/api',
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
})

webhookClient.interceptors.request.use((config) => {
  const key = getStoredWebhookApiKey()
  if (key) {
    config.headers.Authorization = `Bearer ${key}`
  }
  return config
})

const BASE = '/open/v1/webhooks'

export async function getWebhooks(params?: PageParams): Promise<Page<WebhookRead>> {
  const response = await webhookClient.get<Page<WebhookRead>>(BASE, { params })
  return response.data
}

export async function getWebhook(id: number): Promise<WebhookRead> {
  const response = await webhookClient.get<WebhookRead>(`${BASE}/${id}`)
  return response.data
}

export async function createWebhook(data: WebhookCreate): Promise<WebhookCreateResponse> {
  const response = await webhookClient.post<WebhookCreateResponse>(BASE, data)
  return response.data
}

export async function deleteWebhook(id: number): Promise<void> {
  await webhookClient.delete(`${BASE}/${id}`)
}
